using System.Text.Json.Nodes;
using System.Security.Cryptography;
using Microsoft.Data.SqlClient;
namespace MyProjectManagement;
public static class ChangeRequestApi {
 static async Task<JsonObject> Body(HttpContext ctx)=>(await JsonNode.ParseAsync(ctx.Request.Body))?.AsObject()??throw new ApiError(400,"JSON object required");
 static async Task<JsonObject> Load(SqlConnection c,SqlTransaction? tx,Guid workspace,string id){await using var q=new SqlCommand("SELECT Payload,Version FROM dbo.ChangeRequests "+(tx is null?"":"WITH(UPDLOCK,HOLDLOCK) ")+"WHERE WorkspaceId=@w AND Id=TRY_CONVERT(uniqueidentifier,@id)",c,tx);q.Parameters.AddWithValue("@w",workspace);q.Parameters.AddWithValue("@id",id);await using var reader=await q.ExecuteReaderAsync();J.Require(await reader.ReadAsync(),"Change request not found",404);var row=JsonNode.Parse(reader.GetString(0))!.AsObject();row["version"]=reader.GetInt32(1);return row;}
 static async Task Persist(SqlConnection c,SqlTransaction tx,Guid workspace,JsonObject row,bool create=false){int version=(int)J.N(row,"version",0);row["version"]=version+1;var revision=ChangeRequests.Latest(row);if(create)await Db.Exec(c,tx,"INSERT dbo.ChangeRequests(WorkspaceId,Id,ProjectId,InitiatorId,Number,Version,Payload,UpdatedAt) VALUES(@w,@id,@p,@i,@n,@v,@json,SYSUTCDATETIME())",("@w",workspace),("@id",Guid.Parse(J.S(row,"id"))),("@p",J.S(row,"projectId")),("@i",J.S(row,"initiatorId")),("@n",J.S(row,"number")),("@v",version+1),("@json",row.ToJsonString()));else{int count=await Db.Exec(c,tx,"UPDATE dbo.ChangeRequests SET Version=@next,Payload=@json,UpdatedAt=SYSUTCDATETIME() WHERE WorkspaceId=@w AND Id=@id AND Version=@old",("@w",workspace),("@id",Guid.Parse(J.S(row,"id"))),("@old",version),("@next",version+1),("@json",row.ToJsonString()));J.Require(count==1,"CONFLICT: change request was updated. Reload and retry",409);}}
 public static void Map(WebApplication app,Func<HttpContext,Db,Task<AppUser>> current){
 app.Use(async(ctx,next)=>{if(ctx.Request.Path.StartsWithSegments("/api/change-requests")){ctx.Response.Headers.CacheControl="no-store";ctx.Response.Headers["X-Content-Type-Options"]="nosniff";}await next();});
 app.MapGet("/api/change-requests",async(HttpContext ctx,Db db)=>{var u=await current(ctx,db);await using var c=await db.Open();var s=await db.Load(u.Workspace,c);var p=new Policy(s,u);J.Require(p.Active,"Inactive account");var rows=new JsonArray();await using var q=new SqlCommand("SELECT Payload,Version FROM dbo.ChangeRequests WHERE WorkspaceId=@w ORDER BY UpdatedAt DESC",c);q.Parameters.AddWithValue("@w",u.Workspace);await using var r=await q.ExecuteReaderAsync();while(await r.ReadAsync()){var row=JsonNode.Parse(r.GetString(0))!.AsObject();if(!ChangeRequests.Read(p,row))continue;var rev=ChangeRequests.Latest(row);rows.Add(new JsonObject{["id"]=J.S(row,"id"),["number"]=J.S(row,"number"),["projectId"]=J.S(row,"projectId"),["projectName"]=J.S(p.Project(J.S(row,"projectId")),"name")==""?J.S(row,"projectName"):J.S(p.Project(J.S(row,"projectId")),"name"),["initiatorId"]=J.S(row,"initiatorId"),["revision"]=(int)J.N(rev,"number"),["title"]=J.S(rev,"title"),["state"]=J.S(rev,"state"),["pmId"]=J.S(rev,"pmId"),["ctoId"]=J.S(rev,"ctoId"),["version"]=r.GetInt32(1),["updatedAt"]=J.S(row,"updatedAt")});if(rows.Count>=200)break;}return Results.Json(rows);}).RequireAuthorization();
 app.MapGet("/api/change-requests/{id}",async(string id,HttpContext ctx,Db db)=>{var u=await current(ctx,db);await using var c=await db.Open();var s=await db.Load(u.Workspace,c);var row=await Load(c,null,u.Workspace,id);J.Require(ChangeRequests.Read(new Policy(s,u),row),"Change request access denied");return Results.Json(row);}).RequireAuthorization();
 app.MapPost("/api/change-requests",async(HttpContext ctx,Db db)=>{var u=await current(ctx,db);var body=await Body(ctx);await using var c=await db.Open();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var s=await db.Load(u.Workspace,c,tx);var row=ChangeRequests.Create(s,new Policy(s,u),body);await Persist(c,tx,u.Workspace,row,true);await tx.CommitAsync();return Results.Json(row);}).RequireAuthorization();
 app.MapPost("/api/change-requests/{id}/action",async(string id,HttpContext ctx,Db db)=>{var u=await current(ctx,db);var body=await Body(ctx);await using var c=await db.Open();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var s=await db.Load(u.Workspace,c,tx);var row=await Load(c,tx,u.Workspace,id);J.Require(J.N(body,"expectedVersion",-1)==J.N(row,"version"),"CONFLICT: change request changed. Reload before deciding",409);ChangeRequests.Act(s,new Policy(s,u),row,J.S(body,"action"),body);await Persist(c,tx,u.Workspace,row);await tx.CommitAsync();return Results.Json(row);}).RequireAuthorization();
 app.MapPost("/api/change-requests/{id}/documents",async(string id,HttpContext ctx,Db db)=>{var u=await current(ctx,db);var body=await Body(ctx);byte[] bytes;try{bytes=Convert.FromBase64String(J.S(body,"base64"));}catch(FormatException){throw new ApiError(400,"Invalid document data");}J.Require(bytes.Length is >0 and <=5*1024*1024,"Word documents must be between 1 byte and 5 MB",400);var name=J.S(body,"name").Replace('\\','/').Split('/').Last();J.Require(name.Length is >0 and <=120&&!name.Any(char.IsControl),"Use a file name up to 120 characters",400);bool docx=name.EndsWith(".docx",StringComparison.OrdinalIgnoreCase),doc=name.EndsWith(".doc",StringComparison.OrdinalIgnoreCase);J.Require(docx||doc,"Upload a Word .docx or .doc file",400);int paragraphCount=docx?ChangeRequests.Preview(bytes,name).Count:0;if(!docx) J.Require(bytes.Length>=8&&bytes.Take(8).SequenceEqual(new byte[]{0xD0,0xCF,0x11,0xE0,0xA1,0xB1,0x1A,0xE1}),"Invalid legacy Word document",400);
 await using var c=await db.Open();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var s=await db.Load(u.Workspace,c,tx);var row=await Load(c,tx,u.Workspace,id);J.Require(J.N(body,"expectedVersion",-1)==J.N(row,"version"),"CONFLICT: reload before uploading",409);var document=Guid.NewGuid();var type=docx?"application/vnd.openxmlformats-officedocument.wordprocessingml.document":"application/msword";var hash=Convert.ToHexString(SHA256.HashData(bytes));var metadata=new JsonObject{["id"]=document.ToString(),["name"]=name,["size"]=bytes.Length,["paragraphCount"]=paragraphCount,["sha256"]=hash,["uploadedBy"]=new Policy(s,u).Actor,["uploadedAt"]=DateTimeOffset.UtcNow.ToString("O")};J.Require(ChangeRequests.Latest(row)["documents"]!.AsArray().Count<20,"Maximum 20 uploads per revision",400);ChangeRequests.Upload(s,new Policy(s,u),row,metadata);await Db.Exec(c,tx,"INSERT dbo.ChangeRequestDocuments(WorkspaceId,Id,RequestId,RevisionNo,FileName,ContentType,Content,Sha256) VALUES(@w,@id,@r,@n,@name,@type,@bytes,@hash)",("@w",u.Workspace),("@id",document),("@r",Guid.Parse(id)),("@n",(int)J.N(ChangeRequests.Latest(row),"number")),("@name",name),("@type",type),("@bytes",bytes),("@hash",hash));await Persist(c,tx,u.Workspace,row);await tx.CommitAsync();return Results.Json(row);}).RequireAuthorization();
 app.MapGet("/api/change-requests/{id}/documents/{document}",async(string id,string document,HttpContext ctx,Db db)=>{var u=await current(ctx,db);await using var c=await db.Open();var s=await db.Load(u.Workspace,c);var row=await Load(c,null,u.Workspace,id);J.Require(ChangeRequests.Read(new Policy(s,u),row),"Document access denied");await using var q=new SqlCommand("SELECT FileName,ContentType,Content FROM dbo.ChangeRequestDocuments WHERE WorkspaceId=@w AND RequestId=TRY_CONVERT(uniqueidentifier,@r) AND Id=TRY_CONVERT(uniqueidentifier,@d)",c);q.Parameters.AddWithValue("@w",u.Workspace);q.Parameters.AddWithValue("@r",id);q.Parameters.AddWithValue("@d",document);await using var reader=await q.ExecuteReaderAsync();J.Require(await reader.ReadAsync(),"Document not found",404);string name=reader.GetString(0),type=reader.GetString(1);byte[] bytes=(byte[])reader.GetValue(2);ctx.Response.Headers.CacheControl="no-store";ctx.Response.Headers["X-Content-Type-Options"]="nosniff";if(ctx.Request.Query["preview"]=="true")return (IResult)Results.Json(new{fileName=name,paragraphs=ChangeRequests.Preview(bytes,name),note=name.EndsWith(".docx",StringComparison.OrdinalIgnoreCase)?"Read-only text preview. Formatting, images and tracked changes are not reproduced. D numbers identify preview paragraphs for review comments.":"Legacy .doc: download and open in Word. Upload .docx for an in-app text preview."});return Results.File(bytes,type,name);}).RequireAuthorization();
 }
}
